def minimum_total_distance(n, citizens, d):
    # Helper function to calculate the Manhattan distance
    def manhattan_distance(x1, y1, x2, y2):
        return abs(x1 - x2) + abs(y1 - y2)

    # List of all x and y coordinates
    x_coords = sorted(citizen[0] for citizen in citizens)
    y_coords = sorted(citizen[1] for citizen in citizens)

    # Check if it is possible to choose a meeting point within the given distance d
    if manhattan_distance(x_coords[0], y_coords[0], x_coords[-1], y_coords[-1]) > 2 * d:
        return "impossible"

    # Calculate the total distance for a given candidate point (x_star, y_star)
    def calculate_total_distance(x_star, y_star):
        return sum(manhattan_distance(x_star, y_star, x, y) for x, y in citizens)

    # Binary search to find the optimal x_star
    def find_optimal_x():
        left, right = x_coords[0], x_coords[-1]
        while left <= right:
            mid = (left + right) // 2
            if manhattan_distance(mid, y_coords[0], x_coords[-1], y_coords[-1]) <= d:
                left = mid + 1
            else:
                right = mid - 1
        optimal_x = right

        left, right = x_coords[0], x_coords[-1]
        while left <= right:
            mid = (left + right) // 2
            if manhattan_distance(mid, y_coords[0], x_coords[0], y_coords[0]) <= d:
                right = mid - 1
            else:
                left = mid + 1
        optimal_x = min(optimal_x, left)

        return optimal_x

    # Binary search to find the optimal y_star
    def find_optimal_y():
        bottom, top = y_coords[0], y_coords[-1]
        while bottom <= top:
            mid = (bottom + top) // 2
            if manhattan_distance(x_coords[0], mid, x_coords[-1], y_coords[-1]) <= d:
                bottom = mid + 1
            else:
                top = mid - 1
        optimal_y = top

        bottom, top = y_coords[0], y_coords[-1]
        while bottom <= top:
            mid = (bottom + top) // 2
            if manhattan_distance(x_coords[0], mid, x_coords[0], y_coords[0]) <= d:
                top = mid - 1
            else:
                bottom = mid + 1
        optimal_y = min(optimal_y, bottom)

        return optimal_y

    optimal_x = find_optimal_x()
    optimal_y = find_optimal_y()

    # Calculate the smallest possible total distance
    min_distance = float('inf')
    for x_star in range(max(x_coords[0], optimal_x - d), min(x_coords[-1], optimal_x + d) + 1):
        for y_star in range(max(y_coords[0], optimal_y - d), min(y_coords[-1], optimal_y + d) + 1):
            if manhattan_distance(x_star, y_star, x_coords[0], y_coords[0]) <= d:
                min_distance = min(min_distance, calculate_total_distance(x_star, y_star))

    return min_distance

