def min_total_distance(n, coordinates, d):
    x_coords = sorted(x for x, y in coordinates)
    y_coords = sorted(y for x, y in coordinates)

    def possible(x, y):
        return all(abs(x - cx) + abs(y - cy) <= d for cx, cy in coordinates)

    def total_distance(x, y):
        return sum(abs(x - cx) + abs(y - cy) for cx, cy in coordinates)

    # Search in the middle area where most people are
    mid_x = x_coords[n // 2]
    mid_y = y_coords[n // 2]

    # Check around the mid point
    min_distance = float('inf')
    found = False

    for x in range(mid_x - d, mid_x + d + 1):
        for y in range(mid_y - d, mid_y + d + 1):
            if possible(x, y):
                dist = total_distance(x, y)
                if dist < min_distance:
                    min_distance = dist
                    found = True

    if found:
        return min_distance
    else:
        return "impossible"

